using System.Linq;using System.Windows.Forms;
namespace AminPhoneBook { public class ReminderForm:Form { public ReminderForm(PhoneBookData data){Text="یادآوری‌ها";Width=650;Height=420;StartPosition=FormStartPosition.CenterParent;RightToLeft=RightToLeft.Yes;RightToLeftLayout=true;var l=new ListBox{Dock=DockStyle.Fill,Font=new System.Drawing.Font("Tahoma",10)};foreach(var c in data.Contacts.Where(x=>!x.Deleted&&x.NextReminder.HasValue).OrderBy(x=>x.NextReminder))l.Items.Add(c.NextReminder.Value.ToString("yyyy/MM/dd HH:mm")+"  |  "+c.FullName+"  |  "+c.ReminderText);Controls.Add(l);}}}